const STORY_RAVENCROFT = {
  id:'ravencroft', title:'The Ravencroft Heir', genre:'Gothic Horror', genreClass:'genre-gothic',
  cover:'../../Assets/images/cover_shadows.png',
  desc:'Return to a manor built on secrets. Some bloodlines should remain buried.',
  synopsis:'A letter brings you back to the rain-swept estate of your ancestors. The patriarch is dead. The will is sealed. But the house is breathing, and the shadows are waiting.',
  duration:'~90 min', endings:'7 Endings', choiceCount:'150+ Choices',
  startMusic:'anomy5-dark-electronic-464393.mp3',
  stats:[
    {id:'sanity',name:'Sanity',color:'#00cec9',max:100,start:80},
    {id:'bloodline',name:'Bloodline',color:'#c4364a',max:100,start:20},
    {id:'insight',name:'Insight',color:'#d4a843',max:100,start:15}
  ],
  scenes:{},
  episodes:[
    // ═══════ EPISODE 1: THE INVITATION ═══════
    {
      title:'The Invitation',
      desc:'A letter. A storm. A house that remembers your name.',
      thumb:'../../Assets/images/gothic_study_png_1775215757929.png',
      duration:'~15 min', hasPremiumChoice:true,
      startMusic:'anomy5-dark-electronic-464393.mp3',
      startNode:'r1_1',
      nodes:{
        r1_1:{bg:'gothic_study_png_1775215757929.png',video:'R1.mp4',mood:'dark',ambience:'storm',milestone:{icon:'🌑',title:'The Return',desc:'You have entered Ravencroft Estate'},speaker:'narrator',text:'The grandfather clock hasn\'t chimed in thirty years. Not since the night your mother packed you into a carriage and fled this estate, whispering prayers into the dark.',next:'r1_2'},
        r1_2:{speaker:'narrator',text:'Tonight, as lightning crawls across the sky like white veins, you stand where she swore you would never stand again. The Ravencroft estate. And the clock is {italic}ticking{/italic}.',next:'r1_3'},
        r1_3:{speaker:'inner',text:'The letter arrived three days ago. Heavy cream paper, sealed with black wax. The handwriting was unmistakably Lord Blackwood\'s. But Lord Blackwood has been dead for six days.',next:'r1_4'},
        r1_4:{speaker:'inner',text:'Dead men don\'t write letters. Dead men don\'t send carriages at midnight. Dead men don\'t {italic}insist{/italic}.',next:'r1_4b'},
        r1_4b:{speaker:'inner',text:'The carriage driver wouldn\'t meet my eyes. Kept his collar high and his whip hand trembling. When I asked him his name, he whispered: {whisper}"Names have weight in this place, sir. Best travel light."{/whisper}',next:'r1_4c'},
        r1_4c:{speaker:'narrator',text:'The iron gates of Ravencroft open without being touched. They don\'t creak — they {italic}exhale{/italic}. A breath held for thirty years, released at the sight of returning blood.',next:'r1_5'},
        r1_5:{bg:'gothic_study_png_1775215757929.png',ambience:'clock',speaker:'narrator',text:'The foyer smells of wet limestone and something sweeter — roses, maybe, or the memory of roses. Every surface is carved with the Blackwood crest: a raven clutching a bleeding heart.',next:'r1_5b'},
        r1_5b:{speaker:'narrator',text:'A portrait hangs above the fireplace — your grandfather in his prime. But the eyes in the painting track you as you move. Not a trick of light. The pupils dilate when you stare back.',next:'r1_5c'},
        r1_5c:{speaker:'narrator',text:'To your left, a corridor stretches toward the east wing — a faint blue glow pulses from behind a heavy door. To your right, the main staircase spirals upward into oppressive darkness. Ahead, warm light bleeds from the dining room.',choices:[
          {text:'Investigate the blue glow in the east wing.',hint:'Something unnatural beckons',next:'r1_5d',effects:{insight:10}},
          {text:'Approach the staircase. Call out to whoever is above.',hint:'Face the footsteps',next:'r1_5g',effects:{sanity:-5}},
          {text:'Touch the Blackwood crest on the wall. Your blood is the key.',hint:'✦ The house recognizes its heir',premium:true,next:'r1_5h',effects:{bloodline:15,insight:10}}
        ]},
        r1_5d:{speaker:'narrator',text:'The east wing door opens at your touch. Inside: a study, untouched for decades. Dust covers every surface except one — a writing desk. The chair is still warm.',next:'r1_5e'},
        r1_5e:{speaker:'inner',text:'The letter. The same cream paper, the same black wax seal. But this one is addressed to {italic}"The Next One"{/italic}. Not to me by name. To whoever came next.',next:'r1_5f'},
        r1_5f:{speaker:'narrator',text:'Before you can open it, the door slams shut behind you. The blue glow intensifies — then fades completely. When you turn back to the foyer, Victor is waiting.',next:'r1_6'},
        r1_5g:{speaker:'narrator',text:'"HELLO?" Your voice echoes up the stairwell and returns changed — deeper, older, as if the house aged your words before sending them back. No response. Just the storm.',next:'r1_5g2'},
        r1_5g2:{speaker:'inner',text:'The echo sounded like my grandfather\'s voice. The exact cadence, the exact timbre. The house doesn\'t just {italic}hear{/italic} — it {blood}mimics{/blood}.',next:'r1_6'},
        r1_5h:{speaker:'narrator',text:'Your palm presses against the carved raven. The stone is {warm}hot{/warm}. A vibration runs through the wall — through the floor — through your {italic}bones{/italic}. For one blinding instant, you see the estate as it was three hundred years ago: pristine, golden, {glow}alive{/glow}.',next:'r1_5h2'},
        r1_5h2:{speaker:'inner',text:'The vision dissolves. But something lingers — a map of the house burned into my memory. Every room, every passage, every {italic}hidden space{/italic}. The house just showed me its blueprint. Why?',next:'r1_6'},
        r1_6:{speaker:'narrator',text:'Your fingertips brush the mahogany banister. It\'s warm. Not room-temperature warm — {warm}body-warm{/warm}. As though someone was gripping it moments before you arrived.',next:'r1_7'},
        r1_7:{speaker:'inner',text:'Just wood. Just an old house settling in the storm. That\'s what Mother tried to teach me before the nightmares took her voice away.',next:'r1_8'},
        r1_8:{bg:'Victorian mansion\'s hidden passageway.png',speaker:'narrator',text:'A heavy footstep echoes from the gallery above. A lantern\'s sickly yellow glow spills over the balustrade. Victor — the estate\'s caretaker — peers down at you.',next:'r1_9'},
        r1_9:{speaker:'narrator',text:'He looks exactly as he did thirty years ago. Not a single new wrinkle. Not one gray hair more. As if time forgot him — or he made a deal to be forgotten.',next:'r1_10'},
        r1_10:{speaker:'victor',speakerColor:'c-teal',text:'"I told them you wouldn\'t come. I told the master — rest his bones — that Eleanor\'s boy would have her stubbornness." He descends the staircase. "Yet... here stands the final heir."',next:'r1_10b'},
        r1_10b:{speaker:'elias',speakerColor:'c-gold',text:'"You have not aged a day, Victor. Thirty years. Not a single wrinkle." I keep my voice even. "Explain that."',next:'r1_10c'},
        r1_10c:{speaker:'victor',speakerColor:'c-teal',text:'"Loyalty, Master Elias. Loyal service to the house has its... {italic}compensations{/italic}." He pauses on the third step. "Your grandfather was generous. The contract was... fair."',next:'r1_10d'},
        r1_10d:{speaker:'inner',text:'Contract. Not employment. Not devotion. A {blood}contract{/blood}. And the way he says it — quietly, reverently — tells me it was not signed in ink.',next:'r1_11'},
        r1_11:{speaker:'elias',speakerColor:'c-gold',text:'"Lord Blackwood is dead, Victor. The solicitor confirmed it. So who sent the carriage? Who wrote the letter in a dead man\'s handwriting?"',next:'r1_12'},
        r1_12:{speaker:'victor',speakerColor:'c-teal',text:'"Dead is a complicated word in this house, Master Elias. Your grandfather died, yes. But the house... the house has its own ideas about what \'dead\' means."',next:'r1_13'},
        r1_13:{speaker:'inner',text:'He hasn\'t blinked once since he stepped into the light. His eyes are milky, dilated, staring entirely {italic}through{/italic} me. Like he\'s reading something written on the wall behind my skull.',next:'r1_13b'},
        r1_13b:{speaker:'elias',speakerColor:'c-gold',text:'"My mother spent thirty years afraid of this place. What did she {italic}know{/italic} that made her run?"',next:'r1_13c'},
        r1_13c:{speaker:'victor',speakerColor:'c-teal',text:'"She knew the weight of the name. She refused to carry it." A real sadness moves through his voice. "She was braver than you know. She chose {italic}love{/italic} over {italic}legacy{/italic}. The house never forgave her for that."',next:'r1_14'},
        r1_14:{speaker:'victor',speakerColor:'c-teal',text:'"The others are waiting in the dining room. They\'re... {italic}hungry{/italic}. Will you join them, sir?"',next:'r1_15'},
        r1_15:{speaker:'narrator',text:'The word "hungry" lands wrong. Not like an invitation to dinner. Like a warning.',choices:[
          {text:'"The others? I thought I was the only heir."',hint:'Who else is in this house?',next:'r1_16a',effects:{insight:10}},
          {text:'"I\'m not joining anyone until I see the body."',hint:'Demand authority',next:'r1_16b',effects:{bloodline:15}},
          {text:'Study Victor\'s face. Something is deeply wrong with him.',hint:'✦ Read what he\'s hiding',premium:true,next:'r1_16c',effects:{insight:20,sanity:-5}}
        ]},
        r1_16a:{speaker:'victor',speakerColor:'c-teal',text:'"The only {italic}living{/italic} heir, sir. But you are not the only one with a claim to the shadows of this house." He turns and begins walking. His footsteps make no sound.',next:'r1_17'},
        r1_16b:{speaker:'victor',speakerColor:'c-teal',text:'He smiles — his lips stretching too wide, too far, revealing teeth that are slightly too {italic}sharp{/italic}. "The body is everywhere, sir. In the walls. In the floorboards. Lord Blackwood is the house now."',next:'r1_17',effects:{sanity:-5}},
        r1_16c:{speaker:'inner',text:'His pupils are wrong. Not dilated — {blood}absent{/blood}. Solid white orbs with pinpricks of gold light deep inside, like candle flames burning behind frosted glass. Victor isn\'t looking at me. Something inside Victor is.',next:'r1_17'},
        r1_17:{bg:'Decay of a forgotten dining room.png',transition:'VoidFlow.mp4',ambience:'whispers',speaker:'narrator',text:'The dining room is lit by a single candelabra. A feast is laid out — pheasant, rare roast, dark wine in crystal glasses. Opulent, excessive, theatrical.',next:'r1_17b'},
        r1_17b:{speaker:'narrator',text:'The silverware is arranged with surgical precision. Every fork, every knife, every crystal glass positioned to the millimeter. As if the table was set by something that learned human customs from a textbook, not from life.',next:'r1_18'},
        r1_18:{speaker:'narrator',text:'But the smell. Under the rosemary and the candle wax, something is {blood}rotting{/blood}. Sweet, cloying, unmistakable. The food looks fresh and smells like a crypt.',next:'r1_18b'},
        r1_18b:{speaker:'inner',text:'The wine in the glasses isn\'t moving. No meniscus, no reflection. It sits perfectly still, like dark paint poured into crystal. I don\'t think it\'s wine.',next:'r1_19'},
        r1_19:{speaker:'inner',text:'Three guests seated at the table. Two women, one man. Their faces are cast in deep shadow. I listen for breathing. I hear the clock. I hear the storm. I hear {italic}nothing from them{/italic}.',next:'r1_19b'},
        r1_19b:{speaker:'narrator',text:'The candlelight catches something on the table — a fourth place setting, directly across from Victor\'s chair. Empty. The silverware untouched. A glass filled with liquid that moves on its own, swirling slowly.',choices:[
          {text:'Sit in the empty chair. Assert your place.',hint:'Claim authority — this is YOUR house',next:'r1_19c',effects:{bloodline:10}},
          {text:'Remain standing. Don\'t play their game.',hint:'Defiance — refuse the ritual',next:'r1_19f',effects:{sanity:5}},
          {text:'Examine the guests more closely before sitting.',hint:'Observe before committing',next:'r1_19g',effects:{insight:10}},
          {text:'Smell the glass at the empty setting. Trust your senses.',hint:'✦ The liquid reveals a truth',premium:true,next:'r1_19h',effects:{insight:15,sanity:-5}}
        ]},
        r1_19c:{speaker:'narrator',text:'The chair pulls itself out as you approach. You sit. The wood molds to your body like it was carved for you. The guests lean forward — interested, {italic}hungry{/italic}.',next:'r1_19d'},
        r1_19d:{speaker:'inner',text:'The moment I sat down, something changed. The house exhaled. The walls relaxed. As if the estate itself was holding its breath waiting for this moment. The heir at the table. The blood returned.',next:'r1_20'},
        r1_19f:{speaker:'narrator',text:'You plant your feet. "I\'ll stand." Victor\'s expression doesn\'t change, but the guests exchange a look — not displeasure. {italic}Respect{/italic}.',next:'r1_19f2'},
        r1_19f2:{speaker:'guest_1',speakerColor:'c-purple',text:'"He has spine. The mother didn\'t crush that entirely." The woman tilts her head. "Perhaps this one will last longer than the others."',next:'r1_20'},
        r1_19g:{speaker:'inner',text:'I study them carefully. The man\'s hands — too long, fingers jointed in four places instead of three. The women\'s skin has a faint luminescence, like moonlight trapped under porcelain. These aren\'t {italic}people{/italic}.',next:'r1_20'},
        r1_19h:{speaker:'narrator',text:'You lift the glass and inhale. Iron and salt and something {italic}electric{/italic}. Not wine. {blood}Blood{/blood}. But it smells like YOUR blood — the exact scent you associate with scraped knees and childhood accidents.',next:'r1_19h2'},
        r1_19h2:{speaker:'inner',text:'The glass contains my own bloodline, distilled. Three hundred years of Blackwood essence. Victor didn\'t pour this from a bottle — the {italic}house{/italic} produced it. A welcome gift from the abyss.',next:'r1_20'},
        r1_20:{speaker:'guest_1',speakerColor:'c-purple',text:'"He has his grandfather\'s eyes," whispers the woman on the left. But her voice doesn\'t come from her mouth. It resonates from inside your own skull.',next:'r1_21'},
        r1_21:{speaker:'guest_2',speakerColor:'c-amber',text:'"But his mother\'s cowardice," hisses the man. "Look at him tremble. A fragile vessel for the awakening."',next:'r1_22'},
        r1_22:{speaker:'elias',speakerColor:'c-gold',text:'"What is this? A séance? A parlor trick? I came for the will, not ghost stories." Your voice cracks slightly. They notice. {italic}Of course{/italic} they notice.',next:'r1_23'},
        r1_23:{speaker:'victor',speakerColor:'c-teal',text:'"The will is simple, Elias." Victor places a dark, rusted blade on the table between the candelabra. It\'s ancient — the handle wrapped in blackened leather, the edge still sharp.',next:'r1_24'},
        r1_24:{speaker:'victor',speakerColor:'c-teal',text:'"The estate belongs to you. The fortune, the title, all of it. But the {glow}entity{/glow} beneath the estate requires a new anchor. Your grandfather\'s time is finished."',next:'r1_25'},
        r1_25:{speaker:'inner',text:'Entity. He says the word so casually. Like he\'s describing a tenant or a mortgage payment. The entity beneath the estate. As if every family has one of those.',next:'r1_25b'},
        r1_25b:{speaker:'elias',speakerColor:'c-gold',text:'"And if I refuse? What happens to your precious entity if I walk out of here right now?"',next:'r1_25c'},
        r1_25c:{speaker:'victor',speakerColor:'c-teal',text:'"Then the anchor dissolves. And the entity... {blood}feeds{/blood}. Not on one Blackwood heir. On everyone within three miles. The village. The fields. Every living soul."',next:'r1_25d'},
        r1_25d:{speaker:'narrator',text:'The guests nod in unison — a synchronized movement that no living thing would make. Their shadows stretch toward you across the table, reaching like dark fingers.',choices:[
          {text:'"You\'re threatening me with the lives of innocents?"',hint:'Call out the manipulation',next:'r1_25e',effects:{insight:10}},
          {text:'Slam your fist on the table. "I don\'t believe a word of this."',hint:'Deny everything',next:'r1_25f',effects:{sanity:5,bloodline:5}},
          {text:'Stay silent. Let them reveal more.',hint:'Patience is information',next:'r1_25g',effects:{insight:15}},
          {text:'Reach under the table. Something is carved into the wood.',hint:'✦ The table holds a hidden inscription',premium:true,next:'r1_25h',effects:{insight:20}}
        ]},
        r1_25e:{speaker:'victor',speakerColor:'c-teal',text:'"Not threatening, sir. Informing. There is a meaningful difference, though I appreciate your grandfather often struggled with the distinction as well."',next:'r1_26'},
        r1_25f:{fx:'shake',speaker:'narrator',text:'Your fist hits the table. The candelabra topples. In the instant of darkness, you feel every guest turn toward you — not with eyes, but with something {italic}older{/italic} than sight.',next:'r1_25f2'},
        r1_25f2:{speaker:'guest_2',speakerColor:'c-amber',text:'"The boy has {warm}fire{/warm}. Perhaps the blood runs thicker than we feared." The man\'s voice carries approval — and anticipation.',next:'r1_26'},
        r1_25g:{speaker:'narrator',text:'Silence stretches. The guests grow restless. Victor shifts his weight. In the quiet, you hear something new — a rhythmic thudding from below the floor. A heartbeat. The house\'s heartbeat.',next:'r1_26'},
        r1_25h:{speaker:'inner',text:'My fingers find grooves in the wood. Letters carved by desperate hands: {whisper}"DON\'T TRUST THE BUTLER. HE IS THE FIRST. HE IS THE LAST. — M.B. 1891"{/whisper}. Another Blackwood\'s warning, hidden for over a century.',next:'r1_26'},
        r1_26:{bg:'Eerie obsidian bridge over glowing abyss.png',video:'SomeRedAsynchronousRecklessSignals.mp4',fx:'flash',ambience:'heartbeat',speaker:'narrator',text:'The shadows in the room detach from the walls. Not metaphorically — {italic}literally{/italic}. They crawl like ink spilled upward, wrapping around the table legs, reaching toward you.',next:'r1_27'},
        r1_27:{speaker:'narrator',text:'The temperature drops twenty degrees in an instant. Your breath crystallizes. The candles flicker but refuse to die.',choices:[
          {text:'Pick up the blade. "I\'ll anchor nothing. I\'m ending this."',hint:'Aggressive resistance — grab the weapon',next:'r1_28a',effects:{bloodline:15,sanity:-10}},
          {text:'"Tell me everything. What did my family do? What is the pact?"',hint:'Knowledge over action',next:'r1_28b',effects:{insight:20}},
          {text:'Run. Back through the door, into the storm, away from this madness.',hint:'Self-preservation',next:'r1_28c',effects:{sanity:10}},
          {text:'Address the guests directly. "Speak. What are you?"',hint:'Demand answers from the dead',next:'r1_28d',effects:{insight:10,sanity:-5}},
          {text:'Knock the candelabra to the floor. Let chaos decide.',hint:'Unpredictable — create confusion',next:'r1_28e',effects:{bloodline:10}}
        ]},
        r1_28a:{speaker:'narrator',text:'Your hand closes around the handle. It\'s warm — the same body-warmth as the banister. The blade hums against your palm, vibrating with a frequency below sound.',next:'r1_29'},
        r1_28b:{speaker:'victor',speakerColor:'c-teal',text:'"1723. The plague took everything. Crops, cattle, children. But the Blackwoods survived. While the rest of the world burned, they dined on silver. Because they fed the soil with {blood}blood{/blood}."',next:'r1_29'},
        r1_28c:{fx:'shake',speaker:'narrator',text:'You bolt for the door. The handle turns freely but the door won\'t move — as if the wall has grown around it. The house is not {italic}letting you leave{/italic}.',next:'r1_29'},
        r1_28d:{speaker:'guest_1',speakerColor:'c-purple',text:'"We are what remains when the body fails but the {glow}contract{/glow} persists. Former Blackwoods. Former anchors. We served. We suffered. We {italic}endured{/italic}."',next:'r1_28d2'},
        r1_28d2:{speaker:'guest_3',speakerColor:'c-red',text:'"And now we wait for the next. For {italic}you{/italic}, boy. We have waited so very, very long." The golden light in his eye sockets flares.',next:'r1_29'},
        r1_28e:{fx:'shake',speaker:'narrator',text:'The candelabra crashes. Flames lick the tablecloth. In the firelight, the guests are revealed — not solid forms but {blood}constructs{/blood} of shadow and memory, flickering like projections.',next:'r1_28e2'},
        r1_28e2:{speaker:'inner',text:'They\'re not real. Not {italic}fully{/italic} real. They\'re echoes — impressions left on the house by previous anchors. The dining room is a {glow}theater{/glow}, and Victor is the director.',next:'r1_29'},
        r1_29:{speaker:'guest_3',speakerColor:'c-red',text:'The center guest leans forward. He has no eyes. Where they should be, {glow}golden light{/glow} spills out like liquid fire. His mouth opens and a voice older than language speaks:',next:'r1_30'},
        r1_30:{fx:'shake',speaker:'dramatic',text:'{blood}"THE PACT MUST BE RENEWED. THE SOIL IS HUNGRY. THE HEIR HAS COME HOME."{/blood}',next:'r1_31'},
        r1_31:{speaker:'inner',text:'The guests dissolve into ash. The candles die. In perfect darkness, the only light is the golden glow of the blade in my hand and the two burning points where the guest\'s eyes were.',next:'r1_ep_end'},
        r1_ep_end:{
          episodeEnd:true, episodeTitle:'Episode 2: The Crypt',
          episodeSub:'Beneath the floorboards. Beneath the lies. The truth is buried deep.',
          bg:'ravencroft_graveyard_night_1775245753339.png',
          transition:'DottedlilcircletunnelLeadingToASmokyCloudyExploration.mp4',
          speaker:'dramatic',
          text:'{glow}The house is not built on stone. It is built on a promise, made in blood, three hundred years ago. And the ledger is finally due.{/glow}',
          next:'r2_1'
        }
      }
    },
    // ═══════ EPISODE 2: THE CRYPT ═══════
    {
      title:'The Crypt',
      desc:'Descend into the darkness beneath Ravencroft. Face the legacy written in bone.',
      thumb:'../../Assets/images/ravencroft_graveyard_night_1775245753339.png',
      duration:'~15 min', hasPremiumChoice:true,
      startMusic:'alex_makemusic-gorila-315977.mp3',
      startNode:'r2_1',
      nodes:{
        r2_1:{bg:'ravencroft_creepy_attic_1775246210774.png',video:'R2.mp4',mood:'dark',ambience:'wind',milestone:{icon:'⚰️',title:'The Descent',desc:'Into the crypt beneath the manor'},speaker:'narrator',text:'The blade pulses in your hand. In the aftermath of the dining room, the house has gone quiet — not peaceful quiet, but the quiet of something {italic}listening{/italic}.',next:'r2_2'},
        r2_2:{speaker:'victor',speakerColor:'c-teal',text:'"The crypt is below, Master Elias. Your grandfather awaits. He needs to pass the burden before the dawn breaks the seal."',next:'r2_3'},
        r2_3:{speaker:'elias',speakerColor:'c-gold',text:'"The seal. Of course there\'s a seal. Let me guess — it was forged in blood during a lunar eclipse by a one-eyed monk?"',next:'r2_4'},
        r2_4:{speaker:'victor',speakerColor:'c-teal',text:'"Two-eyed. But otherwise accurate." He says this without a trace of humor.',next:'r2_4b'},
        r2_4b:{speaker:'elias',speakerColor:'c-gold',text:'"Victor. Before we go any further." I stop walking. He stops instantly — no overrun, no hesitation. Like a puppet whose strings went still. "How long have you served this house?"',next:'r2_4c'},
        r2_4c:{speaker:'victor',speakerColor:'c-teal',text:'"In my first life, I was appointed caretaker in 1743. I watched your great-great-grandfather plant the oak tree in the east garden." A pause. "It was a good tree."',next:'r2_4d'},
        r2_4d:{speaker:'elias',speakerColor:'c-gold',text:'"And in your {italic}second{/italic} life?"',next:'r2_4e'},
        r2_4e:{speaker:'victor',speakerColor:'c-teal',text:'"Still the caretaker. Still the same halls. Still the same {italic}weight{/italic}." Something moves across his face — not quite grief, but the memory of it. "The pact preserves the body, Master Elias. It is not always merciful enough to {blood}spare the mind{/blood}."',next:'r2_4f'},
        r2_4f:{speaker:'inner',text:'He said that as though he wanted me to understand it was a trap. As though, given the choice again, he would {italic}not{/italic} have signed. Whatever was offered to him in 1743 — immortality, purpose, belonging — it cost more than he expected.',next:'r2_5'},
        r2_5:{speaker:'inner',text:'I\'m following a possibly undead butler into the bowels of a haunted manor carrying a magic knife. My mother died trying to protect me from exactly this moment.',next:'r2_5b'},
        r2_5b:{speaker:'inner',text:'There\'s a painting on every landing we pass. Each one shows a different Blackwood, and each one\'s expression is the same: {italic}terror{/italic}. Frozen mid-scream. I used to think these were artistic choices. Now I think they\'re {blood}snapshots{/blood}.',next:'r2_6'},
        r2_6:{speaker:'inner',text:'But she also died {italic}screaming{/italic}. In an asylum. Because whatever she ran from followed her anyway. Running didn\'t work for her. Maybe fighting will work for me.',next:'r2_6b'},
        r2_6b:{speaker:'narrator',text:'Your hand tightens around the blade. It pulses back — three slow throbs, like a heartbeat synchronizing with yours. The metal is warm now. Almost {warm}comforting{/warm}. Almost {italic}alive{/italic}.',next:'r2_7'},
        r2_7:{bg:'Flashlight in a dark tunnel.png',ambience:'whispers',speaker:'narrator',text:'The descent begins behind a tapestry in the east wing. Stone steps spiral downward into absolute blackness. The lantern in Victor\'s hand barely pushes back the dark.',next:'r2_7b'},
        r2_7b:{speaker:'narrator',text:'Every seventh step is carved with a different face — Blackwood ancestors staring upward from the stone, frozen mid-scream. Their expressions grow more desperate the deeper you go.',choices:[
          {text:'Count the faces. How many anchors served before you?',hint:'The numbers hold meaning',next:'r2_7c',effects:{insight:10}},
          {text:'Keep your eyes on Victor\'s lantern. Don\'t look down.',hint:'Self-preservation',next:'r2_8',effects:{sanity:5}},
          {text:'Touch one of the carved faces. Feel their memory.',hint:'✦ The stone remembers what the flesh forgot',premium:true,next:'r2_7d',effects:{insight:20,sanity:-10}}
        ]},
        r2_7c:{speaker:'inner',text:'Seventeen faces. Seventeen anchors across three centuries. Some lasted decades. One — a child\'s face, no older than ten — is marked with a single scratch. One year of service. They gave a {blood}child{/blood} to the void.',next:'r2_8'},
        r2_7d:{speaker:'narrator',text:'Your fingers brush the fourth face. A jolt rocks through you — a vision: a woman in a white dress, chained to the altar, screaming words in a language you shouldn\'t understand. But you do. She\'s saying: {whisper}"The butler is the lock. The blade is the key. Break one and the other {italic}shatters{/italic}."{/whisper}',next:'r2_8'},
        r2_8:{speaker:'narrator',text:'The walls down here are coated in something slick and warm. In the lantern light, it glistens copper-red. The air tastes metallic.',next:'r2_9'},
        r2_9:{speaker:'narrator',text:'And the whispers begin.',next:'r2_10'},
        r2_10:{speaker:'whispers',speakerColor:'c-narrator',text:'{whisper}...the boy... the boy is here... the mother ran but the blood remembers... we are so hungry...{/whisper}',next:'r2_10b'},
        r2_10b:{speaker:'narrator',text:'The whispers seem to come from everywhere — the walls, the ceiling, the stone beneath your feet. But there\'s a pattern. They\'re not random voices. They\'re answering each {italic}other{/italic}.',choices:[
          {text:'Talk back. "I hear you. What do you want?"',hint:'Engage the whispers directly',next:'r2_10c',effects:{insight:10,sanity:-5}},
          {text:'Cover your ears. Don\'t let them in.',hint:'Protect your mind',next:'r2_11',effects:{sanity:10}},
          {text:'Listen carefully. Try to understand their conversation.',hint:'Eavesdrop on the dead',next:'r2_10e',effects:{insight:15}}
        ]},
        r2_10c:{speaker:'whispers',speakerColor:'c-narrator',text:'{whisper}...he speaks to us... no anchor has spoken to us in eighty years... tell him tell him tell him... VICTOR IS NOT WHAT HE CLAIMS...{/whisper}',next:'r2_11'},
        r2_10e:{speaker:'inner',text:'They\'re debating. About me. Some want to warn me. Others want to consume me. And a third group — the oldest voices, barely audible — are saying something I can\'t quite make out. Something about the {italic}original terms{/italic}.',next:'r2_11'},
        r2_11:{speaker:'elias',speakerColor:'c-gold',text:'"Victor. The walls are whispering." You say it flatly. As if you\'re commenting on wallpaper.',next:'r2_12'},
        r2_12:{speaker:'victor',speakerColor:'c-teal',text:'"They\'ve been whispering for three hundred years, sir. They grow louder when the anchor weakens. Your grandfather held them quiet for sixty years. Remarkable stamina."',next:'r2_13'},
        r2_13:{bg:'Cryptic ritual chamber beneath mansion.png',transition:'LilStimulatingglowy.mp4',ambience:'heartbeat',speaker:'narrator',text:'The passage opens into a vast cavern of ribbed stone — organic curves that look more like the inside of a sleeping leviathan than a family tomb.',next:'r2_14'},
        r2_14:{speaker:'narrator',text:'At the center: a sarcophagus wrapped in iron chains as thick as your wrist. Each chain is covered in runes — the same angular script as on the blade.',next:'r2_15'},
        r2_15:{speaker:'narrator',text:'And the sarcophagus is {shake}moving{/shake}. Rhythmic thuds from inside. Something pushing against the stone lid. Thump. Thump. Like a heartbeat made of fists.',next:'r2_16'},
        r2_16:{speaker:'inner',text:'My grandfather chained himself inside a coffin in a cave beneath his own house. The Blackwood family Christmas must have been {italic}delightful{/italic}.',next:'r2_17'},
        r2_17:{speaker:'victor',speakerColor:'c-teal',text:'"He chained himself when the hunger became uncontrollable. He didn\'t want to harm anyone before you arrived. Despite everything, Master, your grandfather was a good man."',next:'r2_18'},
        r2_18:{speaker:'elias',speakerColor:'c-gold',text:'"A good man who made a pact with an underground entity to keep his estate running. Victor, your definition of \'good\' concerns me."',next:'r2_19'},
        r2_19:{speaker:'narrator',text:'The lid {shake}CRACKS{/shake}. A hand emerges — elongated fingers, tipped in obsidian claws, but recognizably human. Then a face rises.',choices:[
          {text:'Strike the hand with the blade. Sever the connection.',hint:'Violence — instinct over analysis',next:'r2_20a',effects:{bloodline:15},fx:'shake'},
          {text:'"Grandfather? Can you hear me in there?"',hint:'Seek the humanity inside the horror',next:'r2_20b',effects:{sanity:5}},
          {text:'Step back and observe. Let him emerge fully before reacting.',hint:'Patience — see the full picture',next:'r2_20b2',effects:{insight:10}},
          {text:'Look at Victor\'s reaction. His face will tell the truth.',hint:'Read the puppet master',next:'r2_20d',effects:{insight:10}},
          {text:'Place your hand on the sarcophagus lid. Share the blade\'s light with him.',hint:'✦ The runes can purify as well as bind',premium:true,next:'r2_20c',effects:{insight:25}},
          {text:'Command the whispers to help. "Hold him steady!"',hint:'✦ Use the house\'s voices as allies',premium:true,next:'r2_20e',effects:{insight:15,bloodline:10}}
        ]},
        r2_20a:{speaker:'narrator',text:'The blade connects. Light flares where metal meets bone — but it doesn\'t cut. The blade {blood}bonds{/blood}. A dark pulse shoots up your arm. Your grandfather\'s face smiles.',next:'r2_21'},
        r2_20b:{speaker:'grandfather',speakerColor:'c-amber',text:'"Elias..." The voice is a chorus — a hundred voices layered into one crumbling whisper. "Your mother was foolish to hide you. The dark is so {warm}warm{/warm} down here."',next:'r2_21'},
        r2_20b2:{speaker:'narrator',text:'He pulls himself free. The chains dissolve into rust. Standing, he\'s seven feet tall, gaunt, his skin stretched over bones that seem to have too many joints. But the eyes — behind the golden glow — are human. Tired. {italic}Pleading{/italic}.',next:'r2_21'},
        r2_20d:{speaker:'inner',text:'Victor\'s face is... {italic}hungry{/italic}. Not concerned, not afraid. He\'s watching my grandfather emerge the way a diner watches a plate arrive. This isn\'t a rescue. It\'s a {blood}feeding{/blood}.',next:'r2_21'},
        r2_20c:{speaker:'inner',text:'The runes... I can read them. They aren\'t meant to keep him {italic}in{/italic}. They lock the entity {italic}to{/italic} him — prevent it from spreading to the house! He\'s a {blood}containment vessel{/blood}.',next:'r2_21'},
        r2_20e:{speaker:'whispers',speakerColor:'c-narrator',text:'{whisper}...yes yes YES... we hold we hold... for the new blood we hold the old blood steady...{/whisper}',next:'r2_20e2'},
        r2_20e2:{speaker:'narrator',text:'The whispers coalesce into invisible hands, steadying your grandfather as he emerges. His convulsions slow. The entity recedes, just enough. Victor stares at you with an expression you haven\'t seen before: {italic}surprise{/italic}.',next:'r2_21'},
        r2_21:{bg:'Eerie obsidian bridge over glowing abyss.png',speaker:'narrator',text:'He steps out. The chains shatter. What stands before you wears your grandfather\'s skin, but behind the seams, something ancient and vast pushes outward.',next:'r2_22'},
        r2_22:{speaker:'grandfather',speakerColor:'c-amber',text:'"The Blackwood name commands kings because we commanded the darkness itself. Three hundred years of empire, of power, of {glow}immortality{/glow}."',next:'r2_23'},
        r2_23:{speaker:'grandfather',speakerColor:'c-amber',text:'"But the price is an anchor — a living mind to hold the void together. I served sixty years. Your mother was meant to be next. She {blood}fled{/blood}."',next:'r2_24'},
        r2_24:{speaker:'elias',speakerColor:'c-gold',text:'"She chose madness over becoming a battery for a demon. I respect that choice."',next:'r2_25'},
        r2_25:{speaker:'grandfather',speakerColor:'c-amber',text:'"Respect? She chose to die {blood}screaming{/blood} in a padded room! The void remembers its own. You cannot outrun your blood, boy. It SINGS to me from your veins."',next:'r2_26',fx:'shake'},
        r2_26:{speaker:'victor',speakerColor:'c-teal',text:'"The transfer must begin. Strike him, Master Elias. Take the crown of Ravencroft."',next:'r2_27'},
        r2_27:{speaker:'inner',text:'To kill him is to become the anchor. To let him live is to become his food. The trap is perfect. My family designed it to be inescapable. Three hundred years of planning just to put ME in THIS moment.',next:'r2_ep_end'},
        r2_ep_end:{
          episodeEnd:true, episodeTitle:'Episode 3: The Bloodline',
          episodeSub:'The final heir faces the architect of the curse.',
          bg:'Twisted throne in a dark kingdom.png',
          transition:'CirclicFormStackingAsycnchronouslyharmonyThenBlast.mp4',
          speaker:'dramatic',
          text:'{glow}Kill the grandfather and become the vessel. Refuse and be consumed. Or find a third path that three hundred years of Blackwoods never imagined.{/glow}',
          next:'r3_1'
        }
      }
    },
    // ═══════ EPISODE 3: THE BLOODLINE ═══════
    {
      title:'The Bloodline',
      desc:'The confrontation deepens. But the real enemy is older than your grandfather.',
      thumb:'../../Assets/images/Twisted throne in a dark kingdom.png',
      duration:'~15 min', hasPremiumChoice:true,
      startMusic:'alexgrohl-energetic-action-sport-500409.mp3',
      startNode:'r3_1',
      nodes:{
        r3_1:{bg:'Cryptic ritual chamber beneath mansion.png',video:'R3.mp4',mood:'action',ambience:'heartbeat',milestone:{icon:'🗡️',title:'The Bloodline',desc:'Three hundred years culminate here'},speaker:'narrator',text:'The cavern hums with power older than language. Your grandfather advances — a walking ruin, animated by vast cosmic hunger.',next:'r3_2'},
        r3_2:{speaker:'elias',speakerColor:'c-gold',text:'"If I kill you, the entity enters me. If I don\'t, you kill me and take my body anyway." You grip the blade. "The Blackwood trap. Very elegant."',next:'r3_3'},
        r3_3:{speaker:'grandfather',speakerColor:'c-amber',text:'"Elegant? Boy, I spent SIXTY YEARS refining this ritual! Your grandmother died perfecting the containment runes! Show some {italic}appreciation{/italic}!"',next:'r3_4'},
        r3_4:{speaker:'inner',text:'He\'s lecturing me about family values while trying to possess my body. The Blackwood Thanksgiving must have been even worse than the Christmas.',next:'r3_5'},
        r3_5:{speaker:'victor',speakerColor:'c-teal',text:'"Master Elias, respectfully — act now. Dawn approaches. If the entity has no anchor when sunlight touches the estate, it will consume {italic}everything{/italic} within three miles."',next:'r3_6'},
        r3_6:{speaker:'elias',speakerColor:'c-gold',text:'"Everything. You mean the village. Three hundred innocent people."',next:'r3_7'},
        r3_7:{speaker:'victor',speakerColor:'c-teal',text:'"Everyone the Blackwoods have protected for three centuries. The pact wasn\'t purely selfish — the entity is contained. The family sacrifice ensures the safety of thousands."',next:'r3_8'},
        r3_8:{speaker:'inner',text:'He\'s right. And I hate that he\'s right. The Blackwoods weren\'t just parasites — they were {italic}jailers{/italic}. Keeping something horrible locked in their own basement with their own blood.',next:'r3_9'},
        r3_9:{bg:'ravencroft_flooded_chapel_1775279647185.png',video:'WhiteLightComingOutFromBook.mp4',speaker:'narrator',text:'The blade\'s runes flare. You look at them closely. The same angular script as the chains. The blade is not just a weapon — it\'s half of a two-part system.',next:'r3_10'},
        r3_10:{speaker:'inner',text:'The chains bind the entity to a host. The blade transfers between hosts. But what if neither part functions as the Blackwoods intended?',next:'r3_11'},
        r3_11:{speaker:'narrator',text:'Your grandfather lunges — not like an old man, but like a {blood}striking serpent{/blood}. He pins you against the ribbed stone walls. His golden eyes burn inches from yours.',next:'r3_12'},
        r3_12:{speaker:'grandfather',speakerColor:'c-amber',text:'"STRIKE ME! Sink the blade! {shake}FULFILL THE COVENANT{/shake} so I can finally rest! I\'ve been AWAKE for sixty years, Elias! Awake and hungry and alone in the dark!"',next:'r3_13'},
        r3_13:{speaker:'narrator',text:'For a moment — behind the golden light, behind the hunger and the void — you see him. Just an old man. Tired. Afraid. Begging for peace.',next:'r3_14'},
        r3_14:{speaker:'inner',text:'My grandfather. Not a monster. A prison guard who became his own prisoner. Sixty years locked in his own basement, holding the door shut with his bare hands while the darkness ate him alive.',next:'r3_15'},
        r3_15:{bg:'Eerie obsidian bridge over glowing abyss.png',fx:'shake',speaker:'narrator',text:'The cavern cracks. Dust falls like snow. The entity — sensing your hesitation — {blood}surges{/blood}. Tendrils of void crawl from your grandfather\'s mouth, his ears, his eyes.',next:'r3_16'},
        r3_16:{speaker:'narrator',text:'You raise the blade — and a blinding flash erupts from its runes. The light pushes the entity back. Your grandfather collapses. For now.',choices:[
          {text:'Grab your grandfather and drag him deeper into the crypt. There must be another way.',hint:'Refuse the binary choice — seek a third path',next:'r3_17a',effects:{insight:15,sanity:-5}},
          {text:'Turn on Victor. "You orchestrated all of this. WHY?"',hint:'Question the puppet master',next:'r3_17b',effects:{insight:20}},
          {text:'Use the blade\'s flash again. Drive the entity further back.',hint:'Combat — fight the void with light',next:'r3_17d',effects:{bloodline:10,sanity:-5},fx:'flash'},
          {text:'Try to communicate with the entity directly. It\'s not just hunger — it\'s {italic}intelligence{/italic}.',hint:'Speak to the void',next:'r3_17e',effects:{insight:15,sanity:-10}},
          {text:'Use the blade\'s light as a lantern. Explore the crypt walls — the runes tell a story.',hint:'✦ The ancient script holds forbidden knowledge',premium:true,next:'r3_17c',effects:{insight:30}}
        ]},
        r3_17a:{speaker:'narrator',text:'You hoist the old man\'s frail body onto your shoulder. He weighs nothing — the entity has been consuming him from within for decades. Bones and memories.',next:'r3_18'},
        r3_17b:{speaker:'victor',speakerColor:'c-teal',text:'"Orchestrated?" He tilts his head. Not like a human tilts their head. Like an owl — a full 90 degrees. "I have served the Blackwood line since the {italic}first{/italic} anchor, sir."',next:'r3_18'},
        r3_17c:{speaker:'inner',text:'The runes aren\'t just binding spells. They\'re a {glow}history{/glow}. A record. Every anchor, every sacrifice, every Blackwood who served — their final words are carved into these walls.',next:'r3_18'},
        r3_17d:{fx:'flash',speaker:'narrator',text:'The blade flares again. This time the light is stronger — fueled by your anger, your defiance. The void-tendrils recoil, burning, retreating into the cracks between stones.',next:'r3_17d2'},
        r3_17d2:{speaker:'inner',text:'The blade responds to emotion. Not just Blackwood blood — Blackwood {italic}will{/italic}. The stronger my resolve, the brighter it burns. The entity doesn\'t feed on sacrifice. It feeds on {blood}submission{/blood}. And I refuse.',next:'r3_18'},
        r3_17e:{speaker:'narrator',text:'You lower the blade and open your mind. The void floods in — a cacophony of images, sensations, memories that aren\'t yours. Drowning, burning, freezing. And beneath all the noise: one clear, ancient thought.',next:'r3_17e2'},
        r3_17e2:{speaker:'inner',text:'{whisper}"...not hunger... not choice... we are {italic}leashed{/italic}... the keeper holds the chain... free us free us FREE US..."{/whisper} The entity isn\'t evil. It\'s {blood}imprisoned{/blood}. Victor didn\'t contain it — he {italic}enslaved{/italic} it.',next:'r3_18'},
        r3_18:{bg:'Flashlight in a dark tunnel.png',ambience:'whispers',speaker:'narrator',text:'Behind the sarcophagus, hidden by shadow and centuries of dust: a passage. Narrow. Descending further. The whispers pour out of it like cold breath.',next:'r3_19'},
        r3_19:{speaker:'victor',speakerColor:'c-teal',text:'"Master Elias — that passage is forbidden. Your grandfather sealed it decades ago. What lies below the crypt is not meant for living eyes."',next:'r3_20'},
        r3_20:{speaker:'elias',speakerColor:'c-gold',text:'"Nothing in this house is meant for living eyes, Victor. And yet here I am, spectacularly alive and deeply irritated." You step into the passage.',next:'r3_20b'},
        r3_20b:{speaker:'narrator',text:'The passage walls are covered in scratch marks — fingernails dragged across stone. Some are fresh. Some are centuries old. Every Blackwood heir tried to claw their way out of this place at some point.',choices:[
          {text:'Run your fingers along the scratches. Feel their desperation.',hint:'Connect with your ancestors\' suffering',next:'r3_20c',effects:{insight:10,sanity:-5}},
          {text:'Move faster. Don\'t give the house time to trap you.',hint:'Speed over caution',next:'r3_21',effects:{sanity:5}},
          {text:'Follow the deepest set of scratches. They lead somewhere specific.',hint:'✦ Someone carved a message, not random panic',premium:true,next:'r3_20d',effects:{insight:20}}
        ]},
        r3_20c:{speaker:'inner',text:'I feel them. All of them. Every heir who descended into this darkness and realized too late that the choice was never theirs. The stone holds their fear like an archive of suffering.',next:'r3_21'},
        r3_20d:{speaker:'narrator',text:'The scratches form letters: {whisper}"BENEATH THE GALLERY — THE REAL ALTAR — HIS WEAKNESS IS THE SOIL ITSELF — HARRIET 1842"{/whisper}. A breadcrumb from an ancestor two centuries dead. She found something.',next:'r3_21'},
        r3_21:{speaker:'inner',text:'Victor hesitates. For the first time tonight, I see something on his face that isn\'t theatrical devotion. It\'s {italic}fear{/italic}. Whatever is down that passage frightens the unkillable butler.',next:'r3_22'},
        r3_22:{speaker:'narrator',text:'The passage spirals deeper. The walls change — from carved stone to raw bedrock to something {glow}organic{/glow}. The rock breathes. Expands and contracts. You are inside something alive.',next:'r3_ep_end'},
        r3_ep_end:{
          episodeEnd:true, episodeTitle:'Episode 4: The Gallery of Echoes',
          episodeSub:'Every Blackwood heir left their mark. Their screams are the loudest.',
          bg:'ravencroft_portrait_gallery.png',
          transition:'VoidFlow.mp4',
          speaker:'dramatic',
          text:'{glow}The crypt was just the surface. Below it lies the gallery — where three hundred years of Blackwood heirs are preserved in eternal agony. Their memories. Their madness. Their warnings.{/glow}',
          next:'r4_1'
        }
      }
    },
    // ═══════ EPISODE 4: THE GALLERY OF ECHOES ═══════
    {
      title:'The Gallery of Echoes',
      desc:'Every Blackwood heir left their mark. Their screams are the loudest.',
      thumb:'../../Assets/images/ravencroft_portrait_gallery.png',
      duration:'~15 min', hasPremiumChoice:true,
      startMusic:'bodleasons-alone-296348.mp3',
      startNode:'r4_1',
      nodes:{
        r4_1:{bg:'ravencroft_portrait_gallery.png',video:'R4.mp4',mood:'mystery',ambience:'whispers',milestone:{icon:'🖼️',title:'The Gallery of Echoes',desc:'Three centuries of madness preserved in oil and blood'},speaker:'narrator',text:'The passage opens into an impossible space — a gallery the size of a cathedral, stretching in both directions beyond the reach of the blade\'s glow. Portraits line every surface.',next:'r4_2'},
        r4_2:{speaker:'narrator',text:'Not ordinary portraits. Each painting moves. Eyes track you. Mouths open and close in soundless conversation. One woman in a Georgian gown presses her painted hands against the inside of her canvas, as if trying to push through.',next:'r4_3'},
        r4_3:{speaker:'elias',speakerColor:'c-gold',text:'"These are... all Blackwoods?" Your voice echoes in the vast space. From the portraits, a hundred pairs of eyes swivel toward you.',next:'r4_4'},
        r4_4:{speaker:'victor',speakerColor:'c-teal',text:'"Every anchor. Every heir who served. Their consciousness is preserved here — a gift from the entity. Immortality of a sort. They advise the current lord."',next:'r4_5'},
        r4_5:{speaker:'elias',speakerColor:'c-gold',text:'"A gift? They look {italic}trapped{/italic}, Victor. There\'s a difference between preservation and imprisonment."',next:'r4_6'},
        r4_6:{speaker:'inner',text:'The first portrait shows a man in a 1720s frock coat. His nameplate reads: {glow}Aldric Blackwood — First Anchor, 1723-1761{/glow}. His painted eyes are screaming.',next:'r4_7'},
        r4_7:{speaker:'narrator',text:'The painting of Aldric Blackwood shudders. His mouth moves, and this time, you hear the voice — thin, ancient, exhausted:',next:'r4_8'},
        r4_8:{speaker:'aldric',speakerColor:'c-red',text:'"Boy. {warm}Grandson{/warm} of my blood. Listen. Victor {blood}lies{/blood}. He has always lied. The entity was never the danger. The danger was always—"',next:'r4_9'},
        r4_9:{fx:'flash',speaker:'narrator',text:'The painting goes dark. A crack splits the canvas from corner to corner. Victor\'s hand withdraws from the frame — he touched it, and the image died.',next:'r4_10'},
        r4_10:{speaker:'victor',speakerColor:'c-teal',text:'"Forgive Aldric, sir. Three hundred years of confinement have made him... unreliable. The first anchor\'s mind broke centuries ago."',next:'r4_11'},
        r4_11:{speaker:'inner',text:'He silenced Aldric before he could finish his sentence. "The danger was always—" {italic}what{/italic}? The entity? The house? Or {bold}Victor himself{/bold}?',choices:[
          {text:'"What was Aldric about to say, Victor? Finish his sentence."',hint:'Confront Victor directly',next:'r4_12a',effects:{insight:15,sanity:-5}},
          {text:'Touch another portrait. The ancestors want to tell you something.',hint:'Seek the truth from the dead',next:'r4_12b',effects:{insight:20}},
          {text:'While Victor is distracted, read the plaques beneath the portraits. The dates tell a story.',hint:'✦ The timeline reveals a pattern',premium:true,next:'r4_12c',effects:{insight:30}}
        ]},
        r4_12a:{speaker:'victor',speakerColor:'c-teal',text:'"He was going to say the entity, sir. I silenced him to spare you confusion from a broken mind." His eyes don\'t blink. His lips don\'t quite sync with his words.',next:'r4_13'},
        r4_12b:{bg:'ravencroft_portrait_gallery.png',speaker:'narrator',text:'You press your palm against the next portrait — a woman in Victorian dress. Her eyes widen. She grips your hand through the paint.',next:'r4_12b2'},
        r4_12b2:{speaker:'harriet',speakerColor:'c-purple',text:'{whisper}"Harriet Blackwood. Fourth anchor. The butler — Victor — he was here before the first Blackwood ever set foot on this land. He is not a servant. He is the {blood}architect{/blood}."{/whisper}',next:'r4_13'},
        r4_12c:{speaker:'inner',text:'The dates. Aldric: 1723-1761. Margaret: 1761-1798. Thomas: 1798-1842. Each served roughly 40 years. But Victor is listed on {italic}every single plaque{/italic} as "witnessed by." He predates the family.',next:'r4_13'},
        r4_13:{bg:'ravencroft_mirror_labyrinth.png',transition:'LilStimulatingglowy.mp4',ambience:'clock',speaker:'narrator',text:'The gallery narrows into a corridor of mirrors — antique, ornate, each reflecting a different reality. Some show the house in sunlight. Some show it in flames. One shows nothing but {blood}teeth{/blood}.',next:'r4_14'},
        r4_14:{speaker:'narrator',text:'Your reflection walks beside you in the mirrors. But it\'s not quite right. It\'s older. Gaunt. Golden-eyed. It\'s you — after sixty years as the anchor.',next:'r4_15'},
        r4_15:{speaker:'reflection',speakerColor:'c-amber',text:'Your reflection speaks: "Don\'t pity the old man. Pity {italic}yourself{/italic}. We all walked in here thinking we\'d break the cycle. We all became the chain."',next:'r4_16'},
        r4_16:{speaker:'elias',speakerColor:'c-gold',text:'"I\'m not you. I\'m not any of you." You press your hand against the glass. It\'s warm. It yields like skin.',next:'r4_17'},
        r4_17:{speaker:'reflection',speakerColor:'c-amber',text:'"That\'s what I said too. In 1991, when I was twenty-three and brilliant and {italic}certain{/italic}." The reflection fades. Another takes its place — your mother.',next:'r4_18'},
        r4_18:{speaker:'eleanor',speakerColor:'c-purple',text:'"Elias. My beautiful boy. I didn\'t run to protect myself. I ran because Victor told me the entity wanted a {italic}female{/italic} heir for the first time. He wanted to {glow}change the ritual{/glow}."',next:'r4_19'},
        r4_19:{speaker:'elias',speakerColor:'c-gold',text:'"Change it? Change it how?"',next:'r4_20'},
        r4_20:{speaker:'eleanor',speakerColor:'c-purple',text:'"I don\'t know. I ran before I found out. But whatever Victor is planning, Elias — it isn\'t what the Blackwoods agreed to three hundred years ago. He\'s {blood}rewriting the rules{/blood}."',next:'r4_21'},
        r4_21:{speaker:'inner',text:'Mother. Even trapped in a mirror in an impossible gallery beneath a cursed house, she\'s trying to protect me. The thought is warm and devastating.',next:'r4_22'},
        r4_22:{bg:'ravencroft_blood_altar.png',transition:'DottedlilcircletunnelLeadingToASmokyCloudyExploration.mp4',ambience:'heartbeat',speaker:'narrator',text:'The mirrors end. The corridor opens into a stone chamber older than the house itself. In the center: an altar stained with three centuries of dried blood. Runic channels carved in the floor glow faintly crimson.',next:'r4_23'},
        r4_23:{speaker:'narrator',text:'This is not the family crypt. This is the {glow}origin{/glow}. The place where the first pact was signed. And on the altar lies a book — leather-bound, the cover stitched with human hair.',next:'r4_24'},
        r4_24:{speaker:'victor',speakerColor:'c-teal',text:'"We shouldn\'t be here." Victor\'s voice has changed. Lower. Rougher. The mask is slipping. "This chamber is not for the heir. It is for the {italic}architect{/italic}."',next:'r4_25'},
        r4_25:{speaker:'elias',speakerColor:'c-gold',text:'"The architect. That\'s you, isn\'t it, Victor? You weren\'t the first caretaker. You were the first {blood}anything{/blood}."',next:'r4_26'},
        r4_26:{speaker:'narrator',text:'Victor stands perfectly still. The pretense of servitude falls away. His posture changes — straightens. He grows taller. His eyes burn with {glow}ancient gold{/glow}.',choices:[
          {text:'Open the book on the altar. Read the original pact.',hint:'The truth is written — read it before he stops you',next:'r4_27a',effects:{insight:25,sanity:-10}},
          {text:'Attack Victor now, while the mask is down.',hint:'Strike while he\'s vulnerable',next:'r4_27b',effects:{bloodline:20},fx:'shake'},
          {text:'Touch the altar itself. Your blood is the key to this place.',hint:'✦ The altar responds to Blackwood blood',premium:true,next:'r4_27c',effects:{insight:25,bloodline:15}}
        ]},
        r4_27a:{speaker:'narrator',text:'You lunge for the book. It falls open. The pages are written in blood — and you can read every word. The Blackwood gift. The pact wasn\'t with an entity.',next:'r4_28'},
        r4_27b:{speaker:'narrator',text:'The blade connects with Victor\'s chest. He catches it — with his {italic}bare hand{/italic}. No blood. No wound. He smiles with too many teeth.',next:'r4_27b2'},
        r4_27b2:{speaker:'victor',speakerColor:'c-teal',text:'"I am three thousand years old, Master Elias. You\'ll need more than a ritual blade to harm me." He releases the blade. "But I appreciate the {italic}spirit{/italic}."',next:'r4_28'},
        r4_27c:{speaker:'narrator',text:'Your palm touches the stone. The altar {glow}ignites{/glow}. Every rune in the chamber flares to life. The book opens itself. Victor staggers backward — he\'s in {italic}pain{/italic}.',next:'r4_28'},
        r4_28:{speaker:'inner',text:'The original pact. 1723. Written between something called "{glow}The Keeper of the Soil{/glow}" and the village of Ravencroft. Not the Blackwood family — the entire {italic}village{/italic}.',next:'r4_29'},
        r4_29:{speaker:'inner',text:'Victor IS the Keeper. An ancient thing bound to the land. The Blackwoods didn\'t make a deal with the entity beneath the house. They made a deal with {blood}Victor{/blood}.',next:'r4_30'},
        r4_30:{speaker:'victor',speakerColor:'c-teal',text:'"Clever boy." His voice has no pretense now. Deep. Resonant. Older than the stone. "Yes. I am the original. The entity beneath the house is my {italic}shadow{/italic}. My hunger. My price."',next:'r4_31'},
        r4_31:{speaker:'victor',speakerColor:'c-teal',text:'"The Blackwoods didn\'t create the pact. I offered it. Serve as anchor, and the land prospers. Refuse, and the soil takes everything. Three hundred years, and the arrangement has been... {warm}adequate{/warm}."',next:'r4_32'},
        r4_32:{speaker:'elias',speakerColor:'c-gold',text:'"Adequate. You turned my family into batteries for three centuries and you call it {italic}adequate{/italic}?"',next:'r4_33'},
        r4_33:{speaker:'victor',speakerColor:'c-teal',text:'"Would you prefer the alternative? The village consumed. The land barren. Plague and famine and death — the natural state of things before I intervened. I am the {glow}guardian{/glow}, Elias. Not the monster."',next:'r4_34'},
        r4_34:{speaker:'inner',text:'He believes it. That\'s the worst part. Three thousand years old and he genuinely believes he\'s the hero of this story. The benevolent god who only asks for one family\'s eternal suffering in exchange for good harvests.',next:'r4_ep_end'},
        r4_ep_end:{
          episodeEnd:true, episodeTitle:'Episode 5: The Final Reckoning',
          episodeSub:'Every entity has a weakness. Every god can bleed.',
          bg:'ravencroft_entity_revealed.png',
          transition:'CirclicFormStackingAsycnchronouslyharmonyThenBlast.mp4',
          speaker:'dramatic',
          text:'{glow}Victor is the source. The entity is his shadow. The Blackwoods were pawns in a three-thousand-year game. But pawns can reach the other side of the board — and become queens.{/glow}',
          next:'r5_1'
        }
      }
    },
    // ═══════ EPISODE 5: THE FINAL RECKONING ═══════
    {
      title:'The Final Reckoning',
      desc:'The truth is worse than the curse. The cure may be worse than both.',
      thumb:'../../Assets/images/ravencroft_entity_revealed.png',
      duration:'~15 min', hasPremiumChoice:true,
      startMusic:'gvidon-spinning-head-271171.mp3',
      startNode:'r5_1',
      nodes:{
        r5_1:{bg:'ravencroft_entity_revealed.png',video:'R5.mp4',mood:'action',ambience:'heartbeat',milestone:{icon:'⚡',title:'The Final Reckoning',desc:'Face the god beneath the soil'},speaker:'narrator',text:'The altar chamber trembles. Victor\'s true form bleeds through his human shell — vast, ancient, a silhouette made of soil and starlight and three thousand years of hunger.',next:'r5_2'},
        r5_2:{speaker:'victor',speakerColor:'c-teal',text:'"You understand now. The choice was never about your grandfather. It was about whether you would serve {italic}me{/italic} — willingly. A willing anchor is so much more... {warm}efficient{/warm}."',next:'r5_3'},
        r5_3:{speaker:'elias',speakerColor:'c-gold',text:'"You could have forced any of us. Three thousand years of power and you need {italic}consent{/italic}?"',next:'r5_4'},
        r5_4:{speaker:'victor',speakerColor:'c-teal',text:'"Forced anchors decay. Your grandfather lasted sixty years — admirable, but unsustainable. A willing anchor could last {glow}forever{/glow}. An immortal guardian, bound by choice, not chains."',next:'r5_5'},
        r5_5:{speaker:'inner',text:'He\'s offering immortality. Real, actual immortality. Not the painted prison of the gallery — true eternal life. The catch is spending it as a battery for an ancient earth god.',next:'r5_6'},
        r5_6:{speaker:'narrator',text:'Your grandfather crawls from the shadows. Diminished. Almost human again. The entity — Victor\'s shadow — has retreated back to its master. The old man looks up at you with clear, mortal eyes.',next:'r5_7'},
        r5_7:{speaker:'grandfather',speakerColor:'c-amber',text:'"Elias..." His voice is his own now. Broken and small. "I didn\'t know. For sixty years, I thought I was containing a mindless horror. I didn\'t know it was {italic}him{/italic}."',next:'r5_8'},
        r5_8:{speaker:'grandfather',speakerColor:'c-amber',text:'"Victor brought me tea every morning. He read me Shakespeare through the stone. He was my only companion for six {blood}decades{/blood}. And the whole time... he was the thing I was dying to contain."',next:'r5_9'},
        r5_9:{speaker:'elias',speakerColor:'c-gold',text:'"Why? Why the pretense? Why not just reveal yourself?"',next:'r5_10'},
        r5_10:{speaker:'victor',speakerColor:'c-teal',text:'"Because anchors who know the truth fight harder. Your grandmother discovered me in 1974. She tried to destroy the altar. I had to... {italic}remove{/italic} her. Your grandfather was told she died of fever."',next:'r5_11'},
        r5_11:{speaker:'grandfather',speakerColor:'c-amber',text:'The old man\'s face crumbles. "Margaret... you {blood}killed{/blood} Margaret?"',next:'r5_12'},
        r5_12:{speaker:'victor',speakerColor:'c-teal',text:'"She would have destroyed the pact. The village would have starved. I am not cruel, Lord Blackwood. I am {italic}necessary{/italic}."',next:'r5_13'},
        r5_13:{bg:'ravencroft_blood_altar.png',ambience:'storm',speaker:'narrator',text:'The altar pulses. Above ground, you can feel the storm intensifying. Dawn is close. The runes in the floor flicker between crimson and gold.',next:'r5_14'},
        r5_14:{speaker:'victor',speakerColor:'c-teal',text:'"The sun rises in minutes, Elias. Without an anchor, the void consumes the village. Three hundred souls. Farmers, children, the elderly. All dead before breakfast."',next:'r5_15'},
        r5_15:{speaker:'elias',speakerColor:'c-gold',text:'"You keep using them as leverage. \'Accept slavery or I kill innocents.\' That\'s not guardianship, Victor. That\'s {blood}extortion{/blood}."',next:'r5_16'},
        r5_16:{speaker:'victor',speakerColor:'c-teal',text:'"Call it what you wish. The mathematics are simple. One Blackwood suffers so that thousands may live. Your ancestors understood this arithmetic. Why can\'t you?"',next:'r5_17'},
        r5_17:{bg:'ravencroft_mirror_labyrinth.png',speaker:'inner',text:'The mirrors. Mother said Victor was rewriting the rules. The ancestor portraits warned me. The book on the altar held the original pact.',next:'r5_18'},
        r5_18:{speaker:'inner',text:'Think, Elias. Three thousand years old and he needs CONSENT. The original pact was with the VILLAGE, not the family. He changed the terms. He\'s been {italic}cheating{/italic}.',next:'r5_19'},
        r5_19:{speaker:'narrator',text:'You look at the blade. You look at the altar. You look at Victor. And you look at your grandfather. Four elements of an equation that has had the same answer for three centuries.',choices:[
          {text:'"What if I rewrite the pact? Back to the original terms. The whole village shares the burden."',hint:'Redistribute the curse — no single family suffers',next:'r5_20a',effects:{insight:20}},
          {text:'Say nothing. Think nothing. Act.',hint:'Let instinct choose',next:'r5_20b',effects:{bloodline:10}}
        ]},
        r5_20a:{speaker:'victor',speakerColor:'c-teal',text:'Victor\'s golden eyes widen. "You... cannot. The original pact required the {italic}consent of every soul{/italic} in the village. You would need—"',next:'r5_21'},
        r5_20b:{speaker:'narrator',text:'Your fingers find the book on the altar. Your blood drips onto the pages. The words rearrange themselves. The original pact surfaces through centuries of revision.',next:'r5_21'},
        r5_21:{speaker:'elias',speakerColor:'c-gold',text:'"You changed the terms, Victor. The village agreed to SHARE the burden — one season of service per household, rotating. You corrupted it into a permanent bloodline sacrifice because it was more {italic}convenient{/italic}."',next:'r5_22'},
        r5_22:{speaker:'victor',speakerColor:'c-teal',text:'"Convenient? {shake}EFFICIENT.{/shake} Rotating anchors are weak! The seal breaks every transition! I lost half a village in 1720 because a farmer\'s wife couldn\'t hold the void for ONE SEASON!"',next:'r5_23'},
        r5_23:{speaker:'elias',speakerColor:'c-gold',text:'"So you enslaved a single family to solve a logistics problem. Three centuries of Blackwood suffering because you couldn\'t manage a {italic}rotation schedule{/italic}."',next:'r5_24'},
        r5_24:{speaker:'inner',text:'He\'s angry. Good. Angry gods make mistakes. And I can see the mistake he\'s about to make — he\'s going to try to take me by force. Which means consent {italic}does{/italic} matter.',next:'r5_25'},
        r5_25:{bg:'ravencroft_entity_revealed.png',fx:'shake',ambience:'heartbeat',speaker:'narrator',text:'Victor\'s form explodes outward. The butler is gone. What remains is {glow}colossal{/glow} — a being of living earth and shadow, filling the chamber, tendrils of void reaching for you.',next:'r5_26'},
        r5_26:{speaker:'victor',speakerColor:'c-teal',text:'"ENOUGH! Three thousand years I have guarded this land! I will not be lectured by a child who has been alive for {italic}twenty-three pathetic years{/italic}!"',next:'r5_27'},
        r5_27:{speaker:'grandfather',speakerColor:'c-amber',text:'"Elias!" Your grandfather pulls himself upright. Frail. Human. But his eyes are clear. "The blade — it\'s both halves of the system! It can bind AND unbind! Your grandmother figured it out before he—"',next:'r5_28'},
        r5_28:{speaker:'narrator',text:'Victor swats your grandfather aside like a paper doll. The old man hits the wall and doesn\'t move.',next:'r5_final'},
        r5_final:{critical:true,timed:15,timedDefault:'r5_end_accept',bg:'Eerie obsidian bridge over glowing abyss.png',speaker:'dramatic',text:'{glow}The god stands revealed. Your grandfather lies broken. Dawn breaks above. The village sleeps, unknowing. What legacy will you carve into the soil of Ravencroft?{/glow}',choices:[
          {text:'Kneel. "I consent. I will be the willing anchor." Accept immortality and save everyone.',hint:'🌑 POWER — Willing sacrifice for eternal life',next:'r5_end_accept',effects:{bloodline:40},critical:true},
          {text:'Drive the blade into the ALTAR. Destroy the pact itself. Unbind the entity from the land forever.',hint:'🔥 DESTROY — Free the Blackwoods, risk the village',next:'r5_end_destroy',effects:{sanity:30},critical:true,fx:'shake'},
          {text:'Use your blood on the book to RESTORE the original pact. Share the burden across the village.',hint:'✦ ⚖️ JUSTICE — Rewrite three centuries of injustice',premium:true,next:'r5_end_rewrite',effects:{insight:40},critical:true},
          {text:'Stab Victor with the blade. Use the binding runes to imprison HIM in the altar.',hint:'👁 REVERSAL — Cage the jailer',next:'r5_end_cage',effects:{insight:30,bloodline:20},critical:true}
        ]},
        r5_end_accept:{bg:'Twisted throne in a dark kingdom.png',transition:'VoidFlow.mp4',mood:'dark',speaker:'narrator',text:'You kneel. Victor\'s form contracts. The void flows into you like ice water. Agony — then cold perfection. Your eyes burn gold. You feel the land, the soil, every root and stone. Victor bows — genuinely this time. "A {glow}willing{/glow} lord. At last." You smile. The power is {warm}intoxicating{/warm}.',next:'_END',ending:'lord'},
        r5_end_destroy:{bg:'Victorian mansion in flames at night.png',transition:'FlowGoesToCenterThenBlast.mp4',mood:'action',fx:'shake',ambience:'fire',milestone:{icon:'🔥',title:'Break the Cycle',desc:'Ravencroft burns'},speaker:'narrator',text:'The blade sinks into the altar. The stone {shake}SCREAMS{/shake}. Victor howls as the pact shatters. The manor above collapses. Fire erupts from the earth. You drag your grandfather through the inferno into dawn. Ravencroft is ash. The village will struggle — but they are {warm}free{/warm}. Everyone is.',next:'_END',ending:'free'},
        r5_end_rewrite:{bg:'ravencroft_dawn_ruins.png',transition:'GoldenSparkleTunnelForward.mp4',mood:'hopeful',milestone:{icon:'⚖️',title:'The New Covenant',desc:'Justice rewritten in blood'},speaker:'narrator',text:'Your blood rewrites the pact. The original terms restore. Victor shrieks as his power dilutes — spread across every household, a shared whisper instead of one family\'s scream. The Blackwoods are {warm}free{/warm}. The village endures. The burden is light because it is {glow}shared{/glow}. Dawn breaks warm and golden.',next:'_END',ending:'justice'},
        r5_end_cage:{bg:'ravencroft_blood_altar.png',transition:'CrystallizedTimeLapse.mp4',mood:'mystery',milestone:{icon:'🔒',title:'The Jailer Jailed',desc:'Three thousand years in a stone box'},speaker:'narrator',text:'The blade pierces Victor. The binding runes activate — but reversed. Victor is {italic}pulled{/italic} into the altar. Three thousand years of godhood compressed into cold stone. His scream echoes for seventeen seconds, then silence. Your grandfather weeps with relief. You walk out into dawn, the blade heavy in your hand. The new guardian of Ravencroft — on your {warm}own terms{/warm}.',next:'_END',ending:'cage'}
      }
    }
  ],
  endings:{
    lord:{icon:'🌑',title:'The Dark Lord',text:'You accepted the power willingly. The first Blackwood to embrace immortality. The land has never been more alive — or more afraid.',color:'#8a5cf5'},
    free:{icon:'🔥',title:'Break the Cycle',text:'You destroyed the estate, the pact, and three centuries of servitude. The village will struggle. But no Blackwood will ever suffer again.',color:'#e84393'},
    justice:{icon:'⚖️',title:'The New Covenant',text:'You restored the original pact. The burden is shared by the whole village — light enough to bear, fair enough to endure. A true heir\'s legacy.',color:'#d4a843'},
    cage:{icon:'🔒',title:'The Jailer Jailed',text:'You imprisoned the god in his own altar. Three thousand years of tyranny ended by a twenty-three-year-old with a magic knife and a bad attitude.',color:'#00cec9'},
    sacrifice:{icon:'🩸',title:'The Final Heir',text:'You ended your own bloodline to starve the entity forever. Noble, tragic, permanent. The Blackwood name dies with you — and so does the curse.',color:'#c4364a'},
    covenant:{icon:'🤝',title:'The New Partnership',text:'You struck a deal with the entity itself — not servitude, but symbiosis. Two minds sharing one vessel. The first Blackwood to treat the void as an equal.',color:'#10b981'},
    exodus:{icon:'🌅',title:'The Exodus',text:'You freed the gallery portraits — seventeen Blackwood souls finally at peace. The entity dissolved without stored memories to feed on. Victor crumbled to soil. Dawn found you alone in an empty house.',color:'#636e72'}
  }
};
